cypress_script:
describe('Multi-Level Navigation Menu', () => {
  it('should navigate to Sub Item and show nested options', () => {
    cy.visit('https://demoqa.com/menu');
    cy.get('a').contains('Main Item 1').click();
    cy.get('a').contains('Sub Item').should('be.visible');
    cy.get('a').contains('Sub Sub List »').should('be.visible');
  });
  it('should not change URL on Sub Item click', () => {
    cy.visit('https://demoqa.com/menu');
    cy.get('a').contains('Main Item 1').click();
    cy.url().should('eq', 'https://demoqa.com/menu');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

 test.describe('Multi-Level Navigation Menu', () => {
   test('should navigate to Sub Item and show nested options', async ({ page }) => {
     await page.goto('https://demoqa.com/menu');
     await page.click('text=Main Item 1');
     await expect(page.locator('text=Sub Item')).toBeVisible();
     await expect(page.locator('text=Sub Sub List »')).toBeVisible();
   });
   test('should not change URL on Sub Item click', async ({ page }) => {
     await page.goto('https://demoqa.com/menu');
     await page.click('text=Main Item 1');
     expect(page.url()).toBe('https://demoqa.com/menu');
   });
 });
